/* PersonalWorkspace Web M1.2 — update notifications & parent/child tasks; no runtime dependencies. */
(()=>{
'use strict';
const KEY='personalworkspace.web.m1.v1';
const LABELS={bug:'Bug',requirement:'需求',optimization:'优化',test:'测试任务',general:'普通任务',life:'生活待办'};
const STATUSES={todo:'待处理',doing:'进行中',waiting:'等待中',verifying:'待验证',done:'已完成',cancelled:'已取消'};
const PROJECT_STATES={active:'活跃',paused:'暂停',completed:'已完成',archived:'已归档'};
const PRIORITY={low:'低',normal:'普通',high:'高',urgent:'紧急'};
const RECORD_TYPES={analysis:'问题分析',implementation:'处理实施',test:'测试记录',summary:'阶段总结',note:'普通记录'};
const NAV=[['dashboard','◫','今日关注'],['inbox','▤','收集箱'],['items','☷','全部事项'],['projects','▦','工作项目'],['reminders','♧','提醒中心'],['trash','⌫','回收站'],['data','⇵','数据管理']];
const blank=()=>({schemaVersion:1,createdAt:now(),projects:[],items:[],records:[],rounds:[],activities:[],reminders:[]});
function now(){return new Date().toISOString()}
function today(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function uid(prefix='id'){return prefix+'_'+(globalThis.crypto?.randomUUID?.()||`${Date.now()}_${Math.random().toString(36).slice(2)}`)}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function attr(v){return esc(v)}
function fmt(date){if(!date)return '—';let d=new Date(date.length===10?date+'T12:00:00':date);return Number.isNaN(d.getTime())?String(date):d.toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',...(date.length===10?{}:{hour:'2-digit',minute:'2-digit'})})}
function isOpen(i){return !['done','cancelled'].includes(i.status)}
function isComplex(i){return ['bug','requirement','optimization'].includes(i.type)}
function pName(id){return db.projects.find(p=>p.id===id)?.name||'未指定项目'}
function currentProject(id){return db.projects.find(p=>p.id===id&&!p.deletedAt)}
function isArchived(item){return Boolean(item.projectId&&currentProject(item.projectId)?.status==='archived')}
function activeItems(){return db.items.filter(i=>!i.deletedAt)}
// A child stores only its parent ID. Existing M1 tasks without parentId remain root tasks.
// Iterate rather than recurse, and track visited IDs, to tolerate a malformed imported graph.
function descendantsOf(id){
  const found=[],seen=new Set([id]),queue=[id];
  while(queue.length){
    const current=queue.shift();
    for(const child of db.items.filter(x=>x.parentId===current&&!x.deletedAt)){
      if(seen.has(child.id))continue;
      seen.add(child.id);found.push(child);queue.push(child.id);
    }
  }
  return found;
}
function childrenOf(id){return db.items.filter(i=>!i.deletedAt&&i.parentId===id)}
function unfinishedChildren(id){return descendantsOf(id).filter(isOpen)}
function parentChoiceAllowed(id,candidate){
  if(!candidate)return true;
  const p=getItem(candidate);
  return Boolean(p&&!p.deletedAt&&!p.inbox&&!isArchived(p)&&candidate!==id&&!descendantsOf(id).some(x=>x.id===candidate));
}
function pendingChildWarning(id){const n=unfinishedChildren(id).length;return n?`注意：仍有 ${n} 条未完成子事项。完成父事项不会自动完成它们。`:''}
function parentLabel(i){const parent=i.parentId?getItem(i.parentId):null;return parent?parent.title:'原父事项已永久删除'}

function canTouch(item){return !item.deletedAt&&!isArchived(item)}
function getItem(id){return db.items.find(i=>i.id===id)}
function dateClass(i){return isOpen(i)&&i.dueDate&&i.dueDate<today()?'red':i.dueDate===today()?'amber':''}
function important(i){return i.priority==='urgent'||i.priority==='high'||(i.dueDate&&i.dueDate<=today())}
function needsToday(i){return isOpen(i)&&(i.plannedDate===today()||(i.dueDate&&i.dueDate<=today())||(i.followUpDate&&i.followUpDate<=today()))}
function itemScope(i){return i.space==='work'?'工作':i.space==='life'?'生活':'未整理'}
function statusBadge(i){return `<span class="badge ${i.status==='done'?'done':i.status==='waiting'?'waiting':i.status==='cancelled'?'cancelled':''}">${STATUSES[i.status]||'待处理'}</span>`}
function typeTag(i){return `<span class="tag blue">${esc(LABELS[i.type]||i.type)}</span>`}
function empty(title,sub=''){return `<div class="empty"><div class="empty-icon">◌</div><strong>${esc(title)}</strong><p class="muted-small">${esc(sub)}</p></div>`}
function formField(label,name,value='',type='text',required=false,extra=''){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}${required?' *':''}</label><input id="f-${esc(name)}" name="${esc(name)}" type="${esc(type)}" value="${attr(value)}" ${required?'required':''} ${extra}></div>`}
function selectField(label,name,options,selected='',extra=''){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><select id="f-${esc(name)}" name="${esc(name)}" ${extra}>${options.map(([v,t])=>`<option value="${attr(v)}" ${v===selected?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`}
function areaField(label,name,value='',rows=3){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><textarea id="f-${esc(name)}" name="${esc(name)}" rows="${rows}">${esc(value)}</textarea></div>`}
function val(fd,key){return String(fd.get(key)||'').trim()}
function validateParentGraph(items){
  const byId=new Map(items.map(x=>[x.id,x]));
  if(byId.size!==items.length)throw Error('事项 ID 重复');
  for(const item of items){
    if(item.parentId===undefined||item.parentId===null||item.parentId==='')continue;
    if(typeof item.parentId!=='string'||!byId.has(item.parentId))throw Error('事项存在无效上级关联');
    const seen=new Set([item.id]);let current=item;
    while(current.parentId){
      if(seen.has(current.parentId))throw Error('事项上级关联形成循环');
      seen.add(current.parentId);
      current=byId.get(current.parentId);
      if(!current)throw Error('事项存在无效上级关联');
    }
  }
}

function load(){try{const raw=localStorage.getItem(KEY);if(!raw)return blank();const p=JSON.parse(raw);if(p?.schemaVersion!==1)throw Error('数据版本不兼容');for(const key of ['projects','items','records','rounds','activities','reminders'])if(!Array.isArray(p[key]))throw Error('数据缺少 '+key);validateParentGraph(p.items);return p}catch(err){storageError='无法读取本地存储：'+err.message;loadBlocked=true;return blank()}}
let storageError='';let loadBlocked=false;let db=load();let page='dashboard',itemId=null,projectId=null,modalClose=()=>{},scope='all',query='',stateFilter='all',itemSort='updated',isImporting=false;
function save(){if(loadBlocked){storageError='本地数据读取异常，为避免覆盖原始数据已禁止写入；请先备份浏览器原始站点数据。';return false}try{localStorage.setItem(KEY,JSON.stringify(db));storageError='';return true}catch(e){storageError='保存失败：'+e.message;return false}}
function transact(mut,success='已保存'){const before=JSON.stringify(db);try{mut();if(!save())throw Error(storageError);render();if(success)toast(success)}catch(e){db=JSON.parse(before);render();toast('操作未保存：'+e.message,true)}}
function log(itemId,kind,title,description=''){db.activities.push({id:uid('act'),itemId,kind,title,description,at:now()})}
function toast(message,error=false){const root=document.getElementById('toast-root');const n=document.createElement('div');n.className='toast'+(error?' error':'');n.textContent=message;root.append(n);setTimeout(()=>n.remove(),3600)}
function showModal(title,body,formId='',submitLabel='保存',wide=false){document.getElementById('modal-root').innerHTML=`<div class="modal-overlay" data-overlay="1"><div role="dialog" aria-modal="true" aria-label="${attr(title)}" class="modal-dialog ${wide?'modal-wide':''}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭">✕</button></div>${formId?`<form id="${attr(formId)}"><div class="modal-body">${body}</div><div class="modal-actions"><button class="btn btn-outline" type="button" data-action="close-modal">取消</button><button class="btn btn-primary" type="submit">${esc(submitLabel)}</button></div></form>`:`<div class="modal-body">${body}</div><div class="modal-actions"><button class="btn btn-outline" data-action="close-modal">关闭</button></div>`}</div></div>`;const el=document.querySelector('.modal-dialog input:not([type=hidden]),.modal-dialog textarea');if(el)el.focus()}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function navTo(target,id=null){if(target==='item'){if(!getItem(id)||getItem(id).deletedAt){toast('找不到此事项',true);return}itemId=id}else if(target==='project'){if(!currentProject(id)){toast('找不到此项目',true);return}projectId=id}page=target;closeModal();render();window.scrollTo({top:0,behavior:'instant'})}
function shell(content){const title=NAV.find(n=>n[0]===page)?.[2]||(page==='item'?'事项详情':page==='project'?'项目详情':'工作台');return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">✓</div><div><strong>个人工作台</strong><small>PERSONAL WORKSPACE</small></div></div><div class="nav-caption">工作空间</div><nav>${NAV.map(([id,icon,text])=>`<button data-action="nav" data-page="${id}" class="nav-button ${page===id||(page==='item'&&id==='items')||(page==='project'&&id==='projects')?'active':''}" title="${text}"><span class="symbol">${icon}</span><span class="nav-text">${text}</span></button>`).join('')}</nav><div class="sidebar-foot">WEB M1.2 · UPDATE CHECKS<br>离线使用 · 数据保存在此浏览器<br>建议定期导出备份</div></aside><div class="workspace"><header class="topbar"><div class="crumb">PERSONAL WORKSPACE <span class="muted"> / </span> <strong>${esc(title)}</strong></div><div class="top-actions"><div class="search-wrap">⌕ <input id="global-search" type="search" value="${attr(query)}" placeholder="搜索任务标题或描述" aria-label="全局搜索" /></div><button class="btn btn-outline" data-action="nav" data-page="reminders">♧ 提醒 <span class="tag">${dueReminders().length}</span></button><button class="btn btn-primary" data-action="new-item">＋ 新建事项</button></div></header><main class="page">${storageError?`<div class="notice danger" style="margin-bottom:20px">${esc(storageError)}。请立即尝试在“数据管理”导出当前数据。</div>`:''}${content}</main></div></div>`}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1 class="page-title">${title}</h1><div class="page-sub">${sub}</div></div><div class="head-actions">${actions}</div></div>`}
function switcher(){return `<div class="segmented">${[['all','全部'],['work','工作'],['life','生活']].map(([k,t])=>`<button class="${scope===k?'selected':''}" data-action="scope" data-value="${k}">${t}</button>`).join('')}</div>`}
function filtered(list){return list.filter(i=>(scope==='all'||i.space===scope)&&(!query||(i.title+' '+i.description+' '+(LABELS[i.type]||'')).toLowerCase().includes(query.toLowerCase())))}
function quickCapture(){return `<form id="capture-form" class="quick-capture"><span style="font-size:20px;color:#7291c0;align-self:center">✎</span><input type="text" name="title" placeholder="快速记录一件事，按 Enter 收集到收集箱…" maxlength="160" required aria-label="快速收集标题"><button class="btn btn-primary" type="submit">收集</button></form>`}
function taskRow(i,showDone=false){return `<div class="task-row"><div class="task-icon">${i.space==='life'?'♡':i.type==='bug'?'⚑':i.type==='requirement'?'◇':'☷'}</div><div class="task-main"><button class="task-title" data-action="open-item" data-id="${i.id}">${esc(i.title)}</button><div class="task-meta">${typeTag(i)}<span>${esc(itemScope(i))}</span>${i.projectId?`<span>· ${esc(pName(i.projectId))}</span>`:''}${i.parentId?`<span>↳ 上级：${esc(parentLabel(i))}</span>`:''}${i.dueDate?`<span class="tag ${dateClass(i)}">截止 ${fmt(i.dueDate)}</span>`:''}${i.nextAction?`<span>↳ ${esc(i.nextAction.slice(0,46))}</span>`:''}</div></div>${statusBadge(i)}${showDone&&isOpen(i)&&!isComplex(i)&&canTouch(i)?`<button class="mark-done" title="直接完成普通待办" data-action="finish-simple" data-id="${i.id}">✓</button>`:''}</div>`}
function panel(title,content,note=''){return `<section class="panel"><div class="panel-header"><span class="panel-title">${title}</span>${note?`<span class="panel-note">${note}</span>`:''}</div><div class="panel-content">${content}</div></section>`}
function dueReminders(){const time=new Date();return db.reminders.filter(r=>!r.deletedAt&&!r.knownAt&&new Date(r.dateTime).getTime()<=time.getTime()&&getItem(r.itemId)&&!getItem(r.itemId).deletedAt&&isOpen(getItem(r.itemId)))}
function dashboard(){const all=filtered(activeItems().filter(i=>!i.inbox));const todayItems=all.filter(needsToday).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));const overdue=all.filter(i=>isOpen(i)&&i.dueDate&&i.dueDate<today());const waiting=all.filter(i=>i.status==='waiting');const recent=all.filter(i=>isOpen(i)&&i.updatedAt).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,6);const pr=db.projects.filter(p=>!p.deletedAt&&p.status==='active');const reminders=dueReminders().filter(r=>scope==='all'||getItem(r.itemId)?.space===scope);const crossSpace=scope==='work'?dueReminders().filter(r=>getItem(r.itemId)?.space==='life').length:0;return shell(`${pageHead('今日关注',`${fmt(today())} · 先看今天需要处理的事，再继续上次的工作。`, `<button class="btn btn-outline" data-action="new-project">＋ 新建项目</button>`)}${quickCapture()}<div class="toolbar">${switcher()}<span class="muted-small">今日由计划日期、到期日和等待跟进日自动识别，也可以手动安排。</span></div><div class="stats"><div class="stat"><div class="stat-label">今日需关注</div><div class="stat-number">${todayItems.length}</div><div class="stat-foot">自动识别与今日安排</div></div><div class="stat"><div class="stat-label">已逾期事项</div><div class="stat-number" style="color:#bd5760">${overdue.length}</div><div class="stat-foot">截止日期已过，尚未完成</div></div><div class="stat"><div class="stat-label">待跟进</div><div class="stat-number">${waiting.length}</div><div class="stat-foot">处于等待中的事项</div></div><div class="stat"><div class="stat-label">内部提醒</div><div class="stat-number">${reminders.length}</div><div class="stat-foot">已达到提醒条件</div></div></div><div class="layout-two"><div class="stack">${panel('今天准备处理',todayItems.length?todayItems.map(i=>taskRow(i,true)).join(''):empty('今日没有待处理事项','可为已有任务设置今天的计划，或从项目中新建任务。'),`${todayItems.length} 条事项`)}${panel('继续上次的工作',recent.length?recent.map(i=>taskRow(i)).join(''):empty('暂无正在处理的事项','开始处理一项任务后会在这里快速找到它。'),'按最近修改排序')}</div><div class="stack">${panel('活跃项目',pr.length?pr.map(p=>{const its=activeItems().filter(i=>i.projectId===p.id);return `<div class="project-mini"><div class="minw-0"><button class="task-title" data-action="open-project" data-id="${p.id}">${esc(p.name)}</button><div class="muted-small">${its.filter(isOpen).length} 条未完成 · ${its.length} 条总计</div></div><button class="btn btn-small btn-outline" data-action="open-project" data-id="${p.id}">查看 →</button></div>`}).join(''):empty('还没有工作项目','点击右上角“新建项目”开始。'))}${crossSpace?`<div class="notice warning" style="margin-bottom:10px">另有 ${crossSpace} 条生活提醒。切换到“全部”或进入提醒中心查看。</div>`:''}${panel('待处理提醒',reminders.length?reminders.slice(0,5).map(r=>`<div class="task-row"><div class="task-icon">♧</div><div class="task-main"><button class="task-title" data-action="open-item" data-id="${r.itemId}">${esc(getItem(r.itemId).title)}</button><div class="task-meta">${fmt(r.dateTime)}</div></div><button class="btn btn-small btn-outline" data-action="ack-reminder" data-id="${r.id}">已知晓</button></div>`).join(''):empty('暂无到期提醒','可以在事项详情中添加多个提醒。'))}</div></div>`)}
function inbox(){const items=db.items.filter(i=>!i.deletedAt&&i.inbox);return shell(`${pageHead('收集箱','先把事情记下来，再决定属于工作还是生活。',`<button class="btn btn-outline" data-action="new-item">完整创建</button>`)}${quickCapture()}${panel('待整理事项',items.length?items.map(i=>`<div class="task-row"><div class="task-icon">▤</div><div class="task-main"><button class="task-title" data-action="open-item" data-id="${i.id}">${esc(i.title)}</button><div class="task-meta">创建于 ${fmt(i.createdAt)}</div></div><button class="btn btn-primary btn-small" data-action="edit-item" data-id="${i.id}">整理</button></div>`).join(''):empty('收集箱已经清空','快速记录的事项会出现在这里。'),`${items.length} 条未整理`)}`)}
function itemsPage(){let items=filtered(activeItems().filter(i=>!i.inbox));if(stateFilter!=='all')items=items.filter(i=>i.status===stateFilter);items.sort((a,b)=>itemSort==='due'?(a.dueDate||'9999').localeCompare(b.dueDate||'9999'):itemSort==='created'?b.createdAt.localeCompare(a.createdAt):b.updatedAt.localeCompare(a.updatedAt));return shell(`${pageHead('全部事项','统一管理工作与生活中的待办、Bug、需求及优化事项。',`<button class="btn btn-primary" data-action="new-item">＋ 完整创建</button>`)}<div class="toolbar">${switcher()}<div class="filters">${selectField('','stateFilter',[['all','全部状态'],...Object.entries(STATUSES)],stateFilter)}${selectField('','itemSort',[['updated','最近更新'],['due','截止日期'],['created','创建时间']],itemSort)}</div></div><section class="panel" style="overflow-x:auto"><table class="data-table"><thead><tr><th>事项</th><th>类型/空间</th><th>状态</th><th>截止日期</th><th>所属项目</th><th>操作</th></tr></thead><tbody>${items.map(i=>`<tr><td class="primary-cell"><button data-action="open-item" data-id="${i.id}">${esc(i.title)}</button>${i.verificationReview?` <span class="tag amber">验收需复核</span>`:''}${i.parentId?`<div class="muted-small">↳ 上级：${esc(parentLabel(i))}</div>`:''}</td><td>${typeTag(i)} <span class="muted">${itemScope(i)}</span></td><td>${statusBadge(i)}</td><td><span class="tag ${dateClass(i)}">${i.dueDate?fmt(i.dueDate):'—'}</span></td><td>${esc(i.projectId?pName(i.projectId):'—')}</td><td><button class="btn btn-outline btn-small" data-action="open-item" data-id="${i.id}">查看</button></td></tr>`).join('')}</tbody></table>${items.length?'':empty('没有匹配的事项','尝试调整空间、状态或关键词筛选。')}</section>`)}
function projectsPage(){const projects=db.projects.filter(p=>!p.deletedAt);return shell(`${pageHead('工作项目','多个项目并行管理；归档只影响项目的活跃管理，不清除原任务及其历史。',`<button class="btn btn-primary" data-action="new-project">＋ 创建项目</button>`)}<div class="project-grid">${projects.map(p=>{const arr=activeItems().filter(i=>i.projectId===p.id);const done=arr.filter(i=>i.status==='done').length;return `<div class="project-card"><div class="flex-between"><span class="tag blue">工作项目</span><span class="badge ${p.status==='archived'?'cancelled':''}">${PROJECT_STATES[p.status]}</span></div><div class="project-name">${esc(p.name)}</div><div class="project-desc">${esc(p.description||'暂无项目说明')}</div><div class="muted-small" style="margin-top:14px">已完成 ${done} 条 / 共 ${arr.length} 条（仅数量统计）</div><div class="project-footer"><span>${arr.length} 个事项 · ${arr.filter(isOpen).length} 未完成</span><button class="btn btn-outline btn-small" data-action="open-project" data-id="${p.id}">进入项目 →</button></div></div>`}).join('')}</div>${!projects.length?empty('还没有项目','创建第一个工作项目后，即可在项目中管理 Bug、需求和优化任务。'):''}`)}
function projectPage(){const p=currentProject(projectId);if(!p)return projectsPage();const items=activeItems().filter(i=>i.projectId===p.id);const open=items.filter(isOpen),waiting=items.filter(i=>i.status==='waiting');return shell(`${pageHead(esc(p.name),`工作项目 / ${PROJECT_STATES[p.status]} · ${esc(p.description||'暂无项目说明')}`,`<button class="btn btn-outline" data-action="nav" data-page="projects">← 项目列表</button><button class="btn btn-outline" data-action="edit-project" data-id="${p.id}">编辑项目</button><button class="btn btn-danger" data-action="trash-project" data-id="${p.id}">删除项目</button>${p.status!=='archived'?`<button class="btn btn-primary" data-action="new-item" data-project="${p.id}">＋ 新建任务</button>`:`<button class="btn btn-primary" data-action="restore-project" data-id="${p.id}">恢复活跃</button>`}`)}${p.status==='archived'?`<div class="notice warning" style="margin-bottom:18px">此项目已经归档，默认只读。已有提醒仍可在提醒中心查看。恢复活跃后可以修改任务。</div>`:''}<div class="stats"><div class="stat"><div class="stat-label">全部事项</div><div class="stat-number">${items.length}</div></div><div class="stat"><div class="stat-label">未完成</div><div class="stat-number">${open.length}</div></div><div class="stat"><div class="stat-label">待验证</div><div class="stat-number">${items.filter(i=>i.status==='verifying').length}</div></div><div class="stat"><div class="stat-label">等待中</div><div class="stat-number">${waiting.length}</div></div></div>${panel('项目事项',items.length?items.map(i=>taskRow(i)).join(''):empty('项目中还没有事项','从项目详情直接创建第一项工作任务。'),`共 ${items.length} 项`)}`)}

function typeDetails(item){
  const o=item.typeData?.[item.type]||{};
  const mapping={
    bug:[['现象','symptom'],['复现步骤','steps'],['预期结果','expected'],['实际结果','actual'],['定位与结论','cause']],
    requirement:[['需求背景','background'],['功能说明','behavior'],['验收标准','acceptance']],
    optimization:[['当前状况','before'],['优化目标','target'],['效果评估','effect']]
  };
  const fields=mapping[item.type]||[];
  return `${fields.length?`<div class="section-h">${esc(LABELS[item.type])} 专属信息</div>${fields.map(([name,key])=>`<div style="margin:12px 0"><span class="muted-small">${name}</span><div class="body-copy">${esc(o[key]||'尚未填写')}</div></div>`).join('')}`:''}${Object.entries(item.typeData||{}).filter(([key])=>key!==item.type&&Object.values(item.typeData[key]||{}).some(Boolean)).map(([key,obj])=>`<details class="old-type"><summary>历史类型「${esc(LABELS[key]||key)}」的专属信息（保留）</summary>${Object.entries(obj).map(([k,v])=>`<div class="muted-small" style="margin:8px 0">${esc(k)}：${esc(v)}</div>`).join('')}</details>`).join('')}`;
}
function itemPage(){
  const i=getItem(itemId);if(!i||i.deletedAt)return itemsPage();
  const records=db.records.filter(r=>r.itemId===i.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  const rounds=db.rounds.filter(r=>r.itemId===i.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  const activities=db.activities.filter(a=>a.itemId===i.id).sort((a,b)=>b.at.localeCompare(a.at));
  const reminds=db.reminders.filter(r=>r.itemId===i.id&&!r.deletedAt).sort((a,b)=>a.dateTime.localeCompare(b.dateTime));
  const locked=!canTouch(i);
  const children=childrenOf(i.id);
  const parent=i.parentId?getItem(i.parentId):null;
  const unfinished=unfinishedChildren(i.id);
  const relationHtml=`<div class="detail-main">
    ${parent?`<div class="muted-small">上级事项</div><div class="project-mini"><div><strong>${esc(parent.title)}</strong>${parent.deletedAt?'<span class="tag amber">在回收站</span>':''}</div>${!parent.deletedAt?`<button class="btn btn-small btn-outline" data-action="open-item" data-id="${attr(parent.id)}">查看上级 →</button>`:''}</div>`:''}
    ${children.length?children.map(c=>`<div class="project-mini"><div class="minw-0"><button class="task-title" data-action="open-item" data-id="${attr(c.id)}">${esc(c.title)}</button><div class="muted-small">${esc(itemScope(c))} · ${esc(STATUSES[c.status]||c.status)}</div></div>${statusBadge(c)}</div>`).join(''):empty('暂无子事项','在此添加子事项，或在其他事项的编辑窗口选择上级。')}
    <div class="muted-small" style="margin-top:10px">${children.filter(c=>!isOpen(c)).length} 条已结束 · ${children.filter(isOpen).length} 条未完成（直接子事项）</div>
    ${unfinished.length?`<div class="notice warning" style="margin-top:12px">含各级子事项，共 ${unfinished.length} 条未完成；父事项可独立完成。</div>`:''}
    ${!locked?`<button class="btn btn-outline btn-small" style="margin-top:14px" data-action="new-child" data-id="${attr(i.id)}">＋ 新建子事项</button>`:''}
  </div>`;
  const controls=locked?`<span class="tag amber">项目已归档 · 只读</span>`:
    `<button class="btn btn-outline" data-action="edit-item" data-id="${i.id}">✎ 编辑</button>
     <button class="btn btn-outline" data-action="change-status" data-id="${i.id}">状态</button>
     <button class="btn btn-primary" data-action="new-record" data-id="${i.id}">＋ 处理记录</button>`;
  const actionButtons=locked?'':`<div class="inline-actions" style="margin:14px 0">
    ${i.status==='done'?`<button class="btn btn-outline" data-action="reopen" data-id="${i.id}">↺ 重新打开</button>`:''}
    ${i.status==='doing'&&isComplex(i)?`<button class="btn btn-outline" data-action="new-round" data-id="${i.id}">提交正式验证</button>`:''}
    ${['doing','waiting','verifying'].includes(i.status)&&isComplex(i)?`<button class="btn btn-outline" data-action="exception-complete" data-id="${i.id}">例外完成</button>`:''}
    ${!isComplex(i)&&isOpen(i)?`<button class="btn btn-outline" data-action="finish-simple" data-id="${i.id}">✓ 标记完成</button>`:''}
    <button class="btn btn-outline" data-action="new-reminder" data-id="${i.id}">＋ 提醒</button>
    <button class="btn btn-danger" data-action="trash-item" data-id="${i.id}">移入回收站</button>
  </div>`;
  const activeRound=rounds.find(r=>r.status==='open');
  const roundHtml=rounds.length?rounds.map(r=>`<div class="record-card">
    <div class="record-top"><span><strong>第 ${r.number} 轮 · ${esc(r.title)}</strong></span><span class="badge ${r.status==='passed'?'done':r.status==='failed'?'cancelled':''}">${({open:'进行中',passed:'验证通过',failed:'验证失败',blocked:'验证受阻'})[r.status]||r.status}</span></div>
    <div class="body-copy">${esc(r.scope||'')}</div>
    ${(r.tests||[]).map(t=>`<div class="test-line"><span class="tag ${t.result==='pass'?'green':t.result==='fail'?'red':'amber'}">${({pass:'通过',fail:'失败',blocked:'受阻'})[t.result]}</span><div style="flex:1"><strong>${esc(t.name)}</strong><div class="muted-small">预期：${esc(t.expected||'—')} · 实际：${esc(t.actual||'—')}</div></div>${!locked?`<button class="subtle-link" data-action="correct-test" data-round="${r.id}" data-test="${t.id}">更正</button>`:''}<button class="subtle-link" data-action="test-history" data-round="${r.id}" data-test="${t.id}">历史</button></div>`).join('')}
    ${r.status==='open'&&!locked?`<div class="inline-actions" style="margin-top:12px"><button class="btn btn-outline btn-small" data-action="new-test" data-id="${r.id}">＋ 测试项目</button><button class="btn btn-outline btn-small" data-action="verify-pass" data-id="${r.id}">确认验证通过并完成</button><button class="btn btn-outline btn-small" data-action="fail-round" data-id="${r.id}">退回处理</button><button class="btn btn-outline btn-small" data-action="block-round" data-id="${r.id}">验证受阻</button></div>`:''}
    ${r.resultNote?`<div class="muted-small" style="margin-top:10px">本轮结论：${esc(r.resultNote)}</div>`:''}
  </div>`).join(''):empty('尚无正式验证轮次','Bug、需求、优化默认通过正式验证后才能正常完成。');
  const recordHtml=records.length?records.map(r=>`<div class="record-card">
    <div class="record-top"><span class="tag ${r.voidedAt?'red':'blue'}">${r.voidedAt?'已作废':esc(RECORD_TYPES[r.type]||r.type)}</span><span class="muted-small">${fmt(r.createdAt)}</span></div>
    <div class="body-copy" ${r.voidedAt?'style="opacity:.6"':''}>${esc(r.content)}</div>
    ${r.conclusion?`<div style="margin-top:10px" class="body-copy"><strong>结论：</strong>${esc(r.conclusion)}</div>`:''}
    ${r.nextAction?`<div style="margin-top:7px" class="body-copy"><strong>当时的下一步：</strong>${esc(r.nextAction)}</div>`:''}
    ${r.voidedAt?`<div class="notice warning">已作废 · ${esc(r.voidReason||'')}</div>`:''}
    <div class="record-bottom"><span>${(r.versions||[]).length} 次更正 · 历史保留</span><div class="inline-actions"><button class="subtle-link" data-action="record-history" data-id="${r.id}">历史版本</button>${!locked&&!r.voidedAt?`<button class="subtle-link" data-action="correct-record" data-id="${r.id}">更正</button><button class="subtle-link" data-action="void-record" data-id="${r.id}">作废</button>`:''}</div></div>
  </div>`).join(''):empty('尚无处理记录','可记录分析、修改、测试或阶段总结。');
  const remindHtml=reminds.length?reminds.map(r=>`<div class="project-mini"><div><strong>${fmt(r.dateTime)}</strong><div class="muted-small">${r.knownAt?'已知晓':new Date(r.dateTime)<=new Date()?'已到期 · 待处理':'待触发'}</div></div><div class="inline-actions">${!r.knownAt?`<button class="btn btn-small btn-outline" data-action="ack-reminder" data-id="${r.id}">已知晓</button>${!locked?`<button class="btn btn-small btn-outline" data-action="snooze-reminder" data-id="${r.id}">稍后</button>`:''}`:''}</div></div>`).join(''):empty('还没有提醒');
  return shell(`${pageHead(esc(i.title),`${esc(itemScope(i))} / ${esc(LABELS[i.type]||i.type)} ${i.projectId?' / '+esc(pName(i.projectId)):''}`,`<button class="btn btn-outline" data-action="nav" data-page="items">← 全部事项</button>${controls}`)}
  ${i.inbox?'<div class="notice warning" style="margin-bottom:14px">该事项仍在收集箱，点击“编辑”选择工作或生活并进行整理。</div>':''}
  ${i.verificationReview?'<div class="notice danger" style="margin-bottom:14px">⚠ 相关测试结果已被更正，原验收结论需要复核。系统不会自动改写原完成历史。</div>':''}
  ${locked?'<div class="notice warning" style="margin-bottom:14px">项目已归档，任务正文和工作记录暂时只读；提醒仍可知晓。</div>':''}
  <div class="detail-layout"><div class="stack">
  ${panel('当前事项信息',`<div class="detail-main"><div class="inline-actions">${typeTag(i)}${statusBadge(i)}${i.completionMethod==='exception'?'<span class="badge review">例外完成</span>':''}${i.verificationReview?'<span class="badge review">验收需复核</span>':''}</div>
   <div class="details-grid">
    ${[['优先级',PRIORITY[i.priority]||'普通'],['计划日期',fmt(i.plannedDate)],['截止日期',fmt(i.dueDate)],['等待跟进',fmt(i.followUpDate)],['所属项目',i.projectId?pName(i.projectId):'—'],['更新时间',fmt(i.updatedAt)]].map(([a,b])=>`<div class="detail-kv"><small>${a}</small><strong>${esc(b)}</strong></div>`).join('')}
   </div><div class="section-h">事项描述</div><div class="body-copy">${esc(i.description||'暂未填写描述')}</div>
   ${typeDetails(i)}<div class="section-h">下一步行动</div><div class="notice">${esc(i.nextAction||'尚未设置，处理记录中可填写并同步更新。')}</div>
   ${i.completionReason?`<div class="section-h">完成说明</div><div class="notice warning">${esc(i.completionReason)}</div>`:''}
   ${actionButtons}</div>`)}
  ${panel('父子事项',relationHtml,`${children.length} 条直接子事项`)}
  ${panel('处理记录',`<div class="detail-main"><div class="flex-between"><span class="muted-small">每次工作独立追加，更正必须留痕</span>${!locked?`<button class="btn btn-small btn-outline" data-action="new-record" data-id="${i.id}">＋ 添加记录</button>`:''}</div>${recordHtml}</div>`,`${records.length} 条`)}
  ${panel('正式验证',`<div class="detail-main">${!locked&&i.status==='doing'&&isComplex(i)?`<button class="btn btn-outline" data-action="new-round" data-id="${i.id}">＋ 开启新验证轮次</button>`:''}${roundHtml}</div>`,`${rounds.length} 轮`)}
  </div><div class="stack">
  ${panel('内部提醒',`<div class="detail-side">${remindHtml}${!locked?`<button class="btn btn-outline btn-small" style="margin-top:16px" data-action="new-reminder" data-id="${i.id}">＋ 新建提醒</button>`:''}</div>`)}
  ${panel('完整时间线',`<div class="detail-side"><div class="timeline">${activities.length?activities.map(a=>`<div class="timeline-event"><div class="time">${fmt(a.at)}</div><div class="event-label">${esc(a.title)}</div><div class="event-body">${esc(a.description||'')}</div></div>`).join(''):empty('尚无事件')}</div></div>`,`${activities.length} 条`)}
  </div></div>`);
}
function reminderPage(){const reminders=db.reminders.filter(r=>!r.deletedAt&&getItem(r.itemId)&&!getItem(r.itemId).deletedAt&&isOpen(getItem(r.itemId))).sort((a,b)=>a.dateTime.localeCompare(b.dateTime));return shell(`${pageHead('提醒中心','已到时间的内部提醒会在打开工作台时显示。关闭浏览器后不会向外发送通知。')}${panel('提醒列表',reminders.length?reminders.map(r=>`<div class="task-row"><div class="task-icon">♧</div><div class="task-main"><button class="task-title" data-action="open-item" data-id="${r.itemId}">${esc(getItem(r.itemId).title)}</button><div class="task-meta">${fmt(r.dateTime)} · ${r.knownAt?'已知晓':new Date(r.dateTime)<=new Date()?'待处理':'待触发'}</div></div>${!r.knownAt?`<button class="btn btn-small btn-outline" data-action="ack-reminder" data-id="${r.id}">已知晓</button><button class="btn btn-small btn-outline" data-action="snooze-reminder" data-id="${r.id}">稍后</button>`:''}</div>`).join(''):empty('暂无提醒','在事项详情里可以设置多条提醒。'),`${reminders.length} 条`)}`)}
function trashPage(){const items=db.items.filter(i=>i.deletedAt),projects=db.projects.filter(p=>p.deletedAt);return shell(`${pageHead('回收站','误删可以恢复；不会自动清空。永久删除前需要单独确认。')}${panel('已删除项目',projects.length?projects.map(p=>`<div class="project-mini"><div><strong>${esc(p.name)}</strong><div class="muted-small">删除于 ${fmt(p.deletedAt)}</div></div><button class="btn btn-outline btn-small" data-action="restore-trash-project" data-id="${p.id}">恢复项目及所属事项</button></div>`).join(''):empty('暂无项目'),`${projects.length} 个`)}<div style="height:20px"></div>${panel('已删除事项',items.length?items.map(i=>`<div class="project-mini"><div><strong>${esc(i.title)}</strong><div class="muted-small">${fmt(i.deletedAt)} · ${esc(LABELS[i.type]||i.type)}</div></div><div class="inline-actions"><button class="btn btn-outline btn-small" data-action="restore-trash-item" data-id="${i.id}">恢复</button><button class="btn btn-danger btn-small" data-action="permanent-item" data-id="${i.id}">永久删除</button></div></div>`).join(''):empty('暂无事项'),`${items.length} 个`)}`)}
function dataPage(){const counts=[['项目',db.projects.length],['事项',db.items.length],['处理记录',db.records.length],['验证轮次',db.rounds.length],['提醒',db.reminders.length]];return shell(`${pageHead('数据管理','当前 M1.2 的本地备份、恢复及数据说明。')}<div class="stats">${counts.slice(0,4).map(([k,v])=>`<div class="stat"><div class="stat-label">${k}</div><div class="stat-number">${v}</div></div>`).join('')}</div><div class="layout-two"><section class="panel"><div class="panel-header"><span class="panel-title">导出本地数据</span></div><div class="data-box"><p>导出一个 JSON 文件，包含目前已实现的项目、事项、处理记录及更正版本、正式验证轮次、提醒、状态事件和回收站标记。</p><div class="notice warning">这是 M1 数据备份，不包含尚未实现的附件、目标、习惯、订阅等完整 V1.0 模块。请妥善保管导出的文件。</div><div style="height:18px"></div><button class="btn btn-primary" data-action="export">↓ 导出 M1.2 备份</button></div></section><section class="panel"><div class="panel-header"><span class="panel-title">恢复本地备份</span></div><div class="data-box"><p>选择此前导出的 JSON 备份。当前版本采用<strong>整体替换</strong>恢复：确认后，备份将替换此浏览器中当前工作台全部当前工作台数据（含父子关联）。</p><div class="notice danger">恢复前请先导出现有数据。恢复过程会校验文件的基本结构，不会合并两份数据。</div><div style="height:18px"></div><label class="btn btn-outline" for="backup-file">↑ 选择备份文件</label><input type="file" id="backup-file" class="file-input" accept=".json,application/json"/></div></section></div><div style="height:20px"></div>${panel('离线与数据存储说明',`<div class="data-box"><ul class="help-list"><li>无需 .NET、Visual Studio 或数据库安装。核心数据保存在当前浏览器的本地存储中。</li><li>可通过 GitHub Pages 在线打开，或使用 Windows 一键启动脚本在 <code>http://127.0.0.1:8765</code> 本机打开。两个网址的数据相互独立，切换时请先导出再导入 JSON 备份。</li><li>在首次成功联网加载后，该网页支持离线访问；本地服务器运行不需要互联网。</li><li>清除浏览器网站数据、换浏览器、换端口或隐私窗口均可能使原本地数据不可见或消失。</li><li>请定期导出 JSON 备份。当前使用 localStorage，适合 M1 试用，不适合大量附件或海量历史数据。</li></ul></div>`)}`)}
function render(){const root=document.getElementById('app');if(!root)return;root.innerHTML=({dashboard,inbox,items:itemsPage,projects:projectsPage,project:projectPage,item:itemPage,reminders:reminderPage,trash:trashPage,data:dataPage}[page]||dashboard)()}
function projectForm(p){return `<div class="field-grid">${formField('项目名称','name',p?.name||'','text',true,'maxlength="120"')}${selectField('项目状态','status',Object.entries(PROJECT_STATES),p?.status||'active')}<div class="span-2">${areaField('项目说明','description',p?.description||'')}</div></div>`}
function editProject(id){const p=id?currentProject(id):null;if(p&&p.status==='archived'){toast('归档项目只读，请先恢复活跃',true);return}showModal(p?'编辑项目':'创建项目',projectForm(p),id?'edit-project-form':'new-project-form','保存项目');if(id)document.querySelector('#'+ 'edit-project-form').dataset.id=id}
function typeOptions(){return Object.entries(LABELS).map(([k,v])=>[k,v])}
function itemForm(item,defaultProject=''){
  const i=item||{title:'',description:'',type:'bug',priority:'normal',status:'todo',space:defaultProject?'work':'work',projectId:defaultProject,plannedDate:'',dueDate:'',followUpDate:'',nextAction:'',typeData:{}};
  const projects=db.projects.filter(p=>!p.deletedAt).map(p=>[p.id,p.name+(p.status==='archived'?'（已归档）':'')]);
  return `<div class="field-grid">
  <div class="span-2">${formField('事项标题','title',i.title,'text',true,'maxlength="160"')}</div>
  ${selectField('所属空间','space',[['work','工作'],['life','生活']],i.space==='life'?'life':'work')}
  ${selectField('事项类型','type',typeOptions(),i.type)}
  ${selectField('所属工作项目','projectId',[['','不指定项目'],...projects],i.projectId||'')}
  ${selectField('优先级','priority',Object.entries(PRIORITY),i.priority)}
  <div class="span-2">${selectField('上级事项（可选）','parentId',[['','无上级（根事项）'],...activeItems().filter(x=>!x.inbox&&!isArchived(x)&&(!item||parentChoiceAllowed(item.id,x.id))).map(x=>[x.id,x.title+(x.projectId?' · '+pName(x.projectId):'')]),...(i.parentId&&!parentChoiceAllowed(i.id,i.parentId)?[[i.parentId,parentLabel(i)+'（当前上级不可新增关联，可保留）']]:[])],i.parentId||'')}<div class="muted-small">支持跨项目或工作/生活空间关联；不能将事项设为自身或其后代的子事项。</div></div>
  ${formField('计划日期','plannedDate',i.plannedDate,'date')}
  ${formField('截止日期','dueDate',i.dueDate,'date')}
  ${formField('等待跟进日期','followUpDate',i.followUpDate,'date')}
  <div class="span-2">${areaField('任务描述','description',i.description)}</div>
  <div class="span-2">${areaField('下一步行动','nextAction',i.nextAction,2)}</div>
  <div class="span-2"><div class="form-section">专属信息（按当前类型选择填写）</div><div class="muted-small">旧类型字段会永久保留，转换类型不会删除原信息。</div></div>
  ${[['bug','Bug：问题现象','symptom'],['bug','Bug：复现步骤','steps'],['bug','Bug：预期结果','expected'],['bug','Bug：实际结果','actual'],['requirement','需求：背景','background'],['requirement','需求：功能描述','behavior'],['requirement','需求：验收标准','acceptance'],['optimization','优化：现状','before'],['optimization','优化：目标','target'],['optimization','优化：效果','effect']].map(([type,label,key])=>`<div class="field type-specific" data-only-type="${type}">${areaField(label,'spec_'+type+'_'+key,i.typeData?.[type]?.[key]||'',2)}</div>`).join('')}
  </div>`;
}
function toggleTypeFields(){const sel=document.querySelector('#f-type');if(!sel)return;document.querySelectorAll('[data-only-type]').forEach(el=>{el.hidden=el.dataset.onlyType!==sel.value});const projectSelect=document.querySelector('#f-projectId');if(projectSelect)projectSelect.disabled=document.querySelector('#f-space')?.value==='life'}
function editItem(id=null,project='',parentId=''){const i=id?getItem(id):null;if(i&&!canTouch(i)){toast('此事项当前只读',true);return}if(project&&currentProject(project)?.status==='archived'){toast('请先恢复归档项目',true);return}showModal(i?'编辑事项':'完整创建事项',itemForm(i|| (parentId?{title:'',description:'',type:'general',priority:'normal',status:'todo',space:getItem(parentId)?.space||'work',projectId:getItem(parentId)?.projectId||'',parentId,plannedDate:'',dueDate:'',followUpDate:'',nextAction:'',typeData:{}}:null),project),i?'edit-item-form':'new-item-form','保存事项',true);if(i)document.querySelector('#edit-item-form').dataset.id=i.id;toggleTypeFields()}
function recordForm(r){return `<div class="field-grid">${selectField('记录类型','type',Object.entries(RECORD_TYPES),r?.type||'analysis')}<div class="field"></div><div class="span-2">${areaField('本次内容','content',r?.content||'',5)}</div><div class="span-2">${areaField('本次结论','conclusion',r?.conclusion||'',2)}</div><div class="span-2">${areaField('下一步行动','nextAction',r?.nextAction||'',2)}</div>${r?`<div class="span-2">${areaField('更正原因（必填）','reason','',2)}</div>`:`<div class="span-2"><label><input type="checkbox" name="syncNext" checked /> 同步更新事项的当前下一步行动</label></div>`}</div>`}
function newRecord(id){if(!canTouch(getItem(id)))return;showModal('新增处理记录',recordForm(), 'new-record-form','提交记录');document.querySelector('#new-record-form').dataset.id=id}
function correctRecord(id){const r=db.records.find(r=>r.id===id);if(!r||!canTouch(getItem(r.itemId))||r.voidedAt)return;showModal('更正处理记录',recordForm(r),'correct-record-form','保存更正');document.querySelector('#correct-record-form').dataset.id=id}
function recordHistory(id){const r=db.records.find(r=>r.id===id);if(!r)return;const entries=[...(r.versions||[]).map(v=>({...v,old:true})),{type:r.type,content:r.content,conclusion:r.conclusion,nextAction:r.nextAction,at:r.updatedAt||r.createdAt,reason:'当前版本',old:false}];showModal('处理记录 · 历史版本',entries.map((v,k)=>`<div class="record-version"><small>版本 ${k+1} · ${fmt(v.at)} ${v.old?'（旧版）':'（当前）'}</small><div class="body-copy">${esc(v.content)}</div><div class="muted-small">结论：${esc(v.conclusion||'—')} · 下一步：${esc(v.nextAction||'—')}</div><div class="muted-small">原因：${esc(v.reason||'首次提交')}</div></div>`).join(''))}
function newRound(id){if(!canTouch(getItem(id)))return;showModal('开启正式验证',`${formField('本轮标题','title','本轮验证','text',true)}${areaField('验证范围和验收条件','scope','')}`,'new-round-form','提交验证');document.querySelector('#new-round-form').dataset.id=id}
function testForm(t){return `${formField('测试项目名称','name',t?.name||'','text',true)}${areaField('预期结果','expected',t?.expected||'',2)}${areaField('实际结果','actual',t?.actual||'',2)}${selectField('测试结果','result',[['pass','通过'],['fail','失败'],['blocked','受阻']],t?.result||'pass')}${t?areaField('更正原因（必填）','reason','',2):''}`}
function newTest(id){showModal('新增验证测试项目',testForm(),'new-test-form','保存测试');document.querySelector('#new-test-form').dataset.id=id}
function correctTest(roundId,testId){const r=db.rounds.find(x=>x.id===roundId);const t=r?.tests?.find(x=>x.id===testId);if(!t||!canTouch(getItem(r.itemId)))return;showModal('更正测试结果',testForm(t),'correct-test-form','保存更正');const f=document.querySelector('#correct-test-form');f.dataset.round=roundId;f.dataset.test=testId}
function exceptionForm(id){showModal('例外完成 · 必须说明原因',`<div class="notice warning" style="margin-bottom:14px">此操作不代表所有测试通过。完成事件会保留例外标记与原因。</div>${areaField('例外完成原因（必填）','reason','',4)}`,'exception-form','确认例外完成');document.querySelector('#exception-form').dataset.id=id}
function statusForm(id){const i=getItem(id);const paths={todo:['doing','cancelled'],doing:['waiting','verifying','cancelled'],waiting:['doing','todo','cancelled'],verifying:['doing','waiting','cancelled'],done:[],cancelled:['todo']};let options=(paths[i.status]||[]).filter(s=>s!=='verifying'||!isComplex(i));if(i.status==='done'){toast('已完成任务请使用“重新打开”',true);return}if(i.status==='doing'&&isComplex(i))options=options.filter(s=>s!=='verifying');if(!options.length){toast('当前状态没有直接转换选项',true);return}showModal('调整任务状态',selectField('目标状态','status',options.map(s=>[s,STATUSES[s]]),options[0])+areaField('状态变化说明','reason','',2),'status-form','确认状态变化');document.querySelector('#status-form').dataset.id=id}
function reminderForm(){const d=new Date(Date.now()+3600000);const local=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');return formField('提醒日期时间','dateTime',local,'datetime-local',true)}
function confirmAction(title,text,onConfirm,label='确认'){const token=uid('confirm');showModal(title,`<div class="notice warning">${esc(text)}</div><div style="margin-top:22px;text-align:right"><button class="btn btn-danger" data-action="do-confirm" data-token="${token}">${esc(label)}</button></div>`);confirmationCallbacks.set(token,onConfirm)}
const confirmationCallbacks=new Map();
function handleClick(btn){const {action,id,page:target,project:pr,value,round,test,token}=btn.dataset;
  switch(action){
    case 'nav':navTo(target);break;
    case 'open-item':navTo('item',id);break;
    case 'open-project':navTo('project',id);break;
    case 'scope':scope=value;render();break;
    case 'new-project':editProject();break;
    case 'edit-project':editProject(id);break;
    case 'new-item':editItem(null,pr||'');break;
    case 'new-child':{const parent=getItem(id);if(!parent||!canTouch(parent)){toast('上级事项不存在或只读',true);return}editItem(null,'',id);break}
    case 'edit-item':editItem(id);break;
    case 'close-modal':closeModal();break;
    case 'new-record':newRecord(id);break;
    case 'correct-record':correctRecord(id);break;
    case 'record-history':recordHistory(id);break;
    case 'new-round':newRound(id);break;
    case 'new-test':newTest(id);break;
    case 'correct-test':correctTest(round,test);break;
    case 'test-history':{const r=db.rounds.find(x=>x.id===round),t=r?.tests?.find(x=>x.id===test);if(!t)return;const entries=[...(t.versions||[]),t].map((v,j)=>`<div class="record-version"><small>版本 ${j+1} · ${fmt(v.at)}</small><div class="body-copy">${esc(v.name)}：${esc(v.result)} · ${esc(v.actual)}</div><div class="muted-small">更正原因：${esc(v.reason||'首次提交')}</div></div>`).join('');showModal('测试结果版本',entries);break}
    case 'exception-complete':exceptionForm(id);break;
    case 'change-status':statusForm(id);break;
    case 'new-reminder':showModal('添加内部提醒',reminderForm(),'reminder-form');document.querySelector('#reminder-form').dataset.id=id;break;
    case 'finish-simple':{const i=getItem(id);if(!i||isComplex(i)||!canTouch(i))return;const finish=()=>transact(()=>{i.status='done';i.completedAt=now();i.updatedAt=now();i.completionMethod='simple';log(id,'status','事项已完成')},'已标记完成');const warning=pendingChildWarning(id);if(warning)confirmAction('确认完成父事项',warning+' 继续完成当前事项吗？',finish,'仅完成当前事项');else finish();break}
    case 'reopen':{const i=getItem(id);if(!i||!canTouch(i)||i.status!=='done')return;transact(()=>{i.status='doing';i.updatedAt=now();i.completionMethod=null;i.verificationReview=false;log(id,'status','任务重新打开','默认进入进行中，原完成历史保留')},'已重新打开');break}
    case 'ack-reminder':transact(()=>{const r=db.reminders.find(x=>x.id===id);if(!r)return;r.knownAt=now()},'已知晓');break;
    case 'snooze-reminder':showModal('稍后提醒',`${selectField('快捷时间','quick',[['1','1 小时后'],['24','明天此时'],['0','自定义日期时间']],'1')}${formField('自定义日期时间','custom','','datetime-local')}`,'snooze-form','确认稍后');document.querySelector('#snooze-form').dataset.id=id;break;
    case 'verify-pass':{const r=db.rounds.find(x=>x.id===id);if(!r||r.status!=='open')return;const tests=r.tests||[];if(!tests.length||tests.some(t=>t.result!=='pass')){toast('至少需要一个测试项目，且本轮所有测试必须通过。其他情况请选择退回、受阻或例外完成。',true);return}confirmAction('确认验证通过','本轮全部已记录测试均通过。请确认本轮已覆盖必要的验收范围，然后将任务标记为正常完成。'+(pendingChildWarning(r.itemId)?' '+pendingChildWarning(r.itemId):''),()=>transact(()=>{r.status='passed';r.endedAt=now();const i=getItem(r.itemId);i.status='done';i.completedAt=now();i.completionMethod='normal';i.completionReason='本轮已记录测试全部通过，经人工确认达到验收要求';i.updatedAt=now();i.verificationReview=false;log(i.id,'verification','验证通过，任务正常完成',`第 ${r.number} 轮`)},'已正常完成'),'确认完成');break}
    case 'fail-round':case 'block-round':{const r=db.rounds.find(x=>x.id===id);if(!r||r.status!=='open')return;const fail=action==='fail-round';confirmAction(fail?'结束验证并退回处理':'标记验证受阻',fail?'保留全部失败结果，任务返回进行中。':'保留测试结果，任务变为等待中。',()=>transact(()=>{r.status=fail?'failed':'blocked';r.endedAt=now();const i=getItem(r.itemId);i.status=fail?'doing':'waiting';i.updatedAt=now();log(i.id,'verification',fail?'本轮验证退回继续处理':'本轮验证受阻',`第 ${r.number} 轮`)},'已更新验证状态'));break}
    case 'void-record':{const r=db.records.find(x=>x.id===id);if(!r||r.voidedAt)return;showModal('作废已提交记录',areaField('作废原因（必填）','reason','',3),'void-record-form','确认作废');document.querySelector('#void-record-form').dataset.id=id;break}
    case 'trash-item':{const i=getItem(id);if(!i||!canTouch(i))return;confirmAction('移入回收站',`确定将“${i.title}”移入回收站吗？处理记录不会删除。`,()=>{transact(()=>{i.deletedAt=now();i.updatedAt=now();log(i.id,'deleted','移入回收站');page='items'},'已移入回收站')},'移入回收站');break}
    case 'trash-project':{const p=currentProject(id);if(!p)return;confirmAction('删除项目及所属任务',`项目“${p.name}”及其所属任务将一同进入回收站。独立共享笔记不会被删除。`,()=>{transact(()=>{p.deletedAt=now();db.items.filter(i=>i.projectId===id&&!i.deletedAt).forEach(i=>{i.deletedAt=now();i.trashedByProject=id;log(i.id,'deleted','因项目删除进入回收站')});page='projects'},'项目已移入回收站')},'确认删除');break}
    case 'restore-trash-project':{const p=db.projects.find(x=>x.id===id);if(!p)return;transact(()=>{p.deletedAt=null;db.items.filter(i=>i.trashedByProject===id).forEach(i=>{i.deletedAt=null;i.trashedByProject=null;log(i.id,'restore','恢复到项目')})},'已恢复项目及所属事项');break}
    case 'restore-trash-item':{const i=getItem(id);if(!i)return;transact(()=>{i.deletedAt=null;i.trashedByProject=null;if(i.projectId&&!currentProject(i.projectId)){i.projectId='';i.inbox=true;i.space='unassigned';log(id,'restore','恢复到收集箱','原所属项目已不存在')}else log(id,'restore','从回收站恢复事项');i.updatedAt=now()},'已恢复事项');break}
    case 'permanent-item':{const i=getItem(id);if(!i?.deletedAt)return;confirmAction('永久删除','此操作不能通过回收站恢复；请先备份。确认永久删除该事项及对应处理记录、验证和提醒吗？',()=>transact(()=>{for(const child of db.items.filter(x=>x.parentId===id)){child.parentId='';child.updatedAt=now();log(child.id,'relation','上级事项已永久删除，子事项改为根事项')}db.items=db.items.filter(x=>x.id!==id);db.records=db.records.filter(x=>x.itemId!==id);db.rounds=db.rounds.filter(x=>x.itemId!==id);db.activities=db.activities.filter(x=>x.itemId!==id);db.reminders=db.reminders.filter(x=>x.itemId!==id)},'已永久删除'),'确认永久删除');break}
    case 'restore-project':{const p=currentProject(id);if(!p)return;transact(()=>{p.status='active';p.updatedAt=now()},'项目已恢复活跃');break}
    case 'export':{const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`个人工作台_M1.2_备份_${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已生成备份文件');break}
    case 'do-confirm':{const fn=confirmationCallbacks.get(token);confirmationCallbacks.delete(token);closeModal();if(fn)fn();break}
  }
}
function readSpec(fd,old){const data=JSON.parse(JSON.stringify(old||{}));for(const key of fd.keys()){if(key.startsWith('spec_')){const parts=key.split('_');const type=parts[1],field=parts.slice(2).join('_');data[type]??={};data[type][field]=val(fd,key)}}return data}
function submitHandler(form){const f=new FormData(form),id=form.dataset.id;
 switch(form.id){
  case 'capture-form':{const title=val(f,'title');if(!title)return;transact(()=>{const i={id:uid('item'),title,description:'',type:'general',space:'unassigned',inbox:true,status:'todo',priority:'normal',projectId:'',typeData:{},createdAt:now(),updatedAt:now(),plannedDate:'',dueDate:'',followUpDate:'',nextAction:''};db.items.push(i);log(i.id,'created','快速记录进入收集箱')},'已收集到收集箱');break}
  case 'new-project-form':case 'edit-project-form':{const name=val(f,'name');if(!name){toast('请输入项目名称',true);return}transact(()=>{const p=id?currentProject(id):{id:uid('project'),createdAt:now()};if(!p)throw Error('项目不存在');if(p.status==='archived')throw Error('归档项目只读');const before=p.status;p.name=name;p.description=val(f,'description');p.status=val(f,'status');p.updatedAt=now();if(p.status==='archived'&&before!=='archived'){const open=activeItems().filter(i=>i.projectId===p.id&&isOpen(i)).length;if(open&&!window.confirm(`该项目还有 ${open} 条未完成事项，归档不会将其自动完成。确认归档？`))throw Error('已取消归档')}if(!id)db.projects.push(p)},id?'项目已更新':'项目已创建');closeModal();break}
  case 'new-item-form':case 'edit-item-form':{const title=val(f,'title'),space=val(f,'space'),type=val(f,'type');if(!title){toast('请输入事项标题',true);return}const project=space==='work'?val(f,'projectId'):'';const parentId=val(f,'parentId');if(parentId&&!parentChoiceAllowed(id||'__new__',parentId)&&(!id||getItem(id)?.parentId!==parentId)){toast('上级事项无效，或关联会形成循环',true);return}if(project&&currentProject(project)?.status==='archived'){toast('不能加入归档项目',true);return}transact(()=>{const i=id?getItem(id):{id:uid('item'),createdAt:now(),status:'todo',typeData:{}};if(!i)throw Error('事项不存在');if(id&&!canTouch(i))throw Error('只读事项');const previousType=i.type,previousSpace=i.space,previousParent=i.parentId||'';i.parentId=parentId;i.title=title;i.space=space;i.inbox=false;i.type=type;i.priority=val(f,'priority');i.projectId=project;i.description=val(f,'description');i.nextAction=val(f,'nextAction');i.plannedDate=val(f,'plannedDate');i.dueDate=val(f,'dueDate');i.followUpDate=val(f,'followUpDate');i.typeData=readSpec(f,i.typeData);i.updatedAt=now();if(!id){db.items.push(i);log(i.id,'created','创建正式事项',`${LABELS[type]} · ${itemScope(i)}`)}else {log(i.id,'edit','编辑事项基本信息');if(previousType!==type){log(i.id,'type','转换事项类型',`${LABELS[previousType]||previousType} → ${LABELS[type]||type}；原字段保留`);if(db.rounds.some(r=>r.itemId===i.id&&r.status==='passed'))i.verificationReview=true};if(previousSpace!==space)log(i.id,'scope','切换工作生活空间',`${previousSpace} → ${space}`);if(previousParent!==parentId)log(i.id,'relation','调整上级事项',`${previousParent||'无'} → ${parentId||'无'}`)}page='item';itemId=i.id},id?'事项已更新':'事项已创建');closeModal();break}
  case 'new-record-form':{const content=val(f,'content');if(!content){toast('记录内容不能为空',true);return}transact(()=>{const r={id:uid('record'),itemId:id,type:val(f,'type'),content,conclusion:val(f,'conclusion'),nextAction:val(f,'nextAction'),versions:[],createdAt:now(),updatedAt:now()};db.records.push(r);const i=getItem(id);i.updatedAt=now();if(f.has('syncNext')&&r.nextAction)i.nextAction=r.nextAction;log(id,'record',`新增${RECORD_TYPES[r.type]||'处理'}记录`,r.content.slice(0,100))},'处理记录已提交');closeModal();break}
  case 'correct-record-form':{const r=db.records.find(x=>x.id===id),reason=val(f,'reason');if(!r||!reason||!val(f,'content')){toast('更正原因和正文不能为空',true);return}transact(()=>{r.versions??=[];r.versions.push({type:r.type,content:r.content,conclusion:r.conclusion,nextAction:r.nextAction,at:r.updatedAt,reason});r.type=val(f,'type');r.content=val(f,'content');r.conclusion=val(f,'conclusion');r.nextAction=val(f,'nextAction');r.updatedAt=now();getItem(r.itemId).updatedAt=now();log(r.itemId,'correction','更正处理记录',reason)},'已留痕更正');closeModal();break}
  case 'void-record-form':{const r=db.records.find(x=>x.id===id),reason=val(f,'reason');if(!reason){toast('请填写作废原因',true);return}transact(()=>{r.voidedAt=now();r.voidReason=reason;log(r.itemId,'void','作废处理记录',reason)},'已标记作废');closeModal();break}
  case 'new-round-form':{const i=getItem(id);if(!i||i.status!=='doing'||!isComplex(i)){toast('只有进行中的复杂任务可以提交验证',true);return}if(db.rounds.some(r=>r.itemId===id&&r.status==='open')){toast('已有正在进行的验证轮次',true);return}transact(()=>{const count=db.rounds.filter(r=>r.itemId===id).length;db.rounds.push({id:uid('round'),itemId:id,number:count+1,title:val(f,'title')||'本轮验证',scope:val(f,'scope'),createdAt:now(),status:'open',tests:[]});i.status='verifying';i.updatedAt=now();log(id,'verification','提交正式验证',`第 ${count+1} 轮`)},'已进入待验证');closeModal();break}
  case 'new-test-form':{const r=db.rounds.find(x=>x.id===id);if(!r||r.status!=='open'||!val(f,'name')){toast('无效测试项目',true);return}transact(()=>{r.tests??=[];r.tests.push({id:uid('test'),name:val(f,'name'),expected:val(f,'expected'),actual:val(f,'actual'),result:val(f,'result'),versions:[],at:now()});getItem(r.itemId).updatedAt=now();log(r.itemId,'test','记录验证测试',`${val(f,'name')} · ${val(f,'result')}`)},'测试结果已保存');closeModal();break}
  case 'correct-test-form':{const r=db.rounds.find(x=>x.id===form.dataset.round),t=r?.tests.find(x=>x.id===form.dataset.test),reason=val(f,'reason');if(!t||!reason){toast('更正原因不能为空',true);return}transact(()=>{t.versions??=[];t.versions.push({name:t.name,expected:t.expected,actual:t.actual,result:t.result,at:t.at,reason});const old=t.result;t.name=val(f,'name');t.expected=val(f,'expected');t.actual=val(f,'actual');t.result=val(f,'result');t.at=now();const i=getItem(r.itemId);i.updatedAt=now();if(old==='pass'&&t.result!=='pass')i.verificationReview=true;log(r.itemId,'correction','更正测试结果',reason)},'测试结果已留痕更正');closeModal();break}
  case 'exception-form':{const reason=val(f,'reason'),i=getItem(id);if(!reason||!i||!['doing','waiting','verifying'].includes(i.status)){toast('请选择有效状态并填写原因',true);return}if(pendingChildWarning(id)&&!window.confirm(pendingChildWarning(id)+' 仍然例外完成此事项吗？'))return;transact(()=>{const r=db.rounds.find(r=>r.itemId===id&&r.status==='open');if(r){r.status='blocked';r.endedAt=now();r.resultNote='任务例外完成，原验证未全部通过'}i.status='done';i.completedAt=now();i.completionMethod='exception';i.completionReason=reason;i.updatedAt=now();log(id,'status','任务例外完成',reason)},'已例外完成');closeModal();break}
  case 'status-form':{const i=getItem(id),target=val(f,'status');if(!i||!canTouch(i))return;const paths={todo:['doing','cancelled'],doing:['waiting','cancelled'],waiting:['doing','todo','cancelled'],verifying:['doing','waiting','cancelled'],cancelled:['todo']};if(!(paths[i.status]||[]).includes(target)){toast('不允许的状态转换',true);return}transact(()=>{const from=i.status;i.status=target;i.updatedAt=now();if(from==='verifying'){const r=db.rounds.find(r=>r.itemId===id&&r.status==='open');if(r){r.status='blocked';r.endedAt=now();r.resultNote='用户手动调整了任务状态'}}log(id,'status','任务状态变更',`${STATUSES[from]} → ${STATUSES[target]}；${val(f,'reason')}`)},'状态已更新');closeModal();break}
  case 'reminder-form':{const dt=val(f,'dateTime');if(!dt){toast('请选择提醒时间',true);return}transact(()=>{db.reminders.push({id:uid('reminder'),itemId:id,dateTime:new Date(dt).toISOString(),createdAt:now(),knownAt:null});log(id,'reminder','新建内部提醒',dt)},'提醒已保存');closeModal();break}
  case 'snooze-form':{const r=db.reminders.find(x=>x.id===id);if(!r)return;const quick=val(f,'quick'),custom=val(f,'custom');if(quick==='0'&&!custom){toast('请选择自定义提醒时间',true);return}transact(()=>{r.dateTime=quick==='0'?new Date(custom).toISOString():new Date(Date.now()+Number(quick)*3600000).toISOString();r.knownAt=null;log(r.itemId,'reminder','稍后提醒',r.dateTime)},'提醒时间已更新');closeModal();break}
 }
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;e.preventDefault();handleClick(button)});
document.addEventListener('submit',e=>{e.preventDefault();submitHandler(e.target)});
document.addEventListener('change',e=>{if(e.target.id==='f-type'||e.target.id==='f-space')toggleTypeFields();if(e.target.id==='f-stateFilter'||e.target.id==='f-itemSort'){stateFilter=e.target.id==='f-stateFilter'?e.target.value:stateFilter;itemSort=e.target.id==='f-itemSort'?e.target.value:itemSort;render()}if(e.target.id==='backup-file'){const file=e.target.files?.[0];if(!file)return;if(file.size>10*1024*1024){toast('文件过大，超出恢复上限（10MB）',true);return}file.text().then(raw=>{let imported;try{imported=JSON.parse(raw);if(!imported||imported.schemaVersion!==1)throw Error('数据版本不支持');for(const key of ['projects','items','records','rounds','activities','reminders'])if(!Array.isArray(imported[key]))throw Error('缺少 '+key);for(const collection of ['projects','items','records','rounds','activities','reminders'])for(const obj of imported[collection]){if(!obj||typeof obj!=='object'||!(/^[a-zA-Z0-9_-]{3,150}$/).test(obj.id))throw Error(collection+' 中存在非法对象 ID')}for(const i of imported.items)if(typeof i.title!=='string'||!i.title.trim()||typeof i.type!=='string')throw Error('事项数据不完整');validateParentGraph(imported.items)}catch(err){toast('备份无效：'+err.message,true);return}confirmAction('确认整体替换恢复',`将从文件“${file.name}”恢复 ${imported.items.length} 个事项。当前本地工作台的内容将被替换，请确保已备份。`,()=>{const previous=db;db=imported;const beforeBlocked=loadBlocked;loadBlocked=false;if(!save()){loadBlocked=beforeBlocked;db=previous;toast('恢复保存失败，已保留当前数据',true);return}page='dashboard';itemId=null;render();toast('备份恢复成功')},'确认替换恢复')}).catch(err=>toast('读取文件失败：'+err.message,true))}});
let searchDelay;
document.addEventListener('input',e=>{if(e.target.id==='global-search'){const text=e.target.value;clearTimeout(searchDelay);searchDelay=setTimeout(()=>{query=text;const focused=document.activeElement?.id==='global-search';const caret=e.target.selectionStart;render();if(focused){const input=document.getElementById('global-search');input?.focus();try{input?.setSelectionRange(caret,caret)}catch{}}},220)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
render();
})();
